275	// isFlagPassed reports whether the named flag was explicitly set on the
276	// command line, so an optional flag with a zero default can be distinguished
277	// from its absence.
278	func isFlagPassed(fs *flag.FlagSet, name string) bool {
279		passed := false
280		fs.Visit(func(f *flag.Flag) {
281			if f.Name == name {
282				passed = true
283			}
284		})
285		return passed
286	}
