299			die("--node is required")
300		}
301	
302		store, err := edgefleet.OpenStore(*dataDir)
303		if err != nil {
304			die("%v", err)
305		}
306		records, err := store.History(*node)
307		if err != nil {
308			die("%v", err)
309		}
310		if len(records) == 0 {
311			fmt.Printf("node=%s no heartbeats\n", *node)
312			return
313		}
314		for _, r := range records {
315			fmt.Printf("node=%s seq=%d collected_at=%s version=%s height=%d missed=%d\n",
316				r.NodeID, r.Seq, r.CollectedAt.Format(time.RFC3339), r.Version, r.Height, r.Missed)
317		}
318	}
