320	func runDemo() {
321		nodes := []edgefleet.Node{
322			{ID: "val-eu-1", Region: "eu", Version: "1.26.0", Online: true},
323			{ID: "val-us-1", Region: "us", Version: "1.25.4", Online: true, Missed: 3},
324			{ID: "edge-ap-1", Region: "ap", Version: "1.26.0", Online: false},
325		}
326		unhealthy := 0
327		for _, node := range nodes {
328			health := edgefleet.Evaluate(node, "1.26.0", 1)
329			if !health.Healthy {
330				unhealthy++
331			}
332			fmt.Printf("node=%s healthy=%v findings=%v\n", health.Node, health.Healthy, health.Findings)
333		}
334		fmt.Println("rollout order:", edgefleet.Plan(nodes, "1.26.0"))
335		fmt.Printf("summary: %d of %d nodes need attention\n", unhealthy, len(nodes))
336	}
