1	package edgefleet
2	
3	// Regression coverage for health queries over disconnected-and-replayed
4	// telemetry. A node may hold heartbeats whose seqs have gaps and whose arrival
5	// order disagrees with both seq order and collection-time order: a record
6	// buffered during an outage can arrive late, a smaller seq can arrive after a
7	// larger one, and the same record can be re-submitted at an even later receive
8	// time. These tests pin the query contract:
9	//
10	//   - "latest telemetry" is strictly the record with the greatest seq, never
11	//     the most recently received one or the one with the newest collection
12	//     time; every displayed field (time, version, height, cumulative missed)
13	//     comes from that one record and fields are never spliced across records;
14	//   - replaying an older, smaller-seq record at a later receive time neither
15	//     refreshes the latest collection time nor flips any judgement;
16	//   - the online boundary is exact at sub-second precision: age == 60s stays
17	//     online, age == 60s + 1 nanosecond is offline, independently of the
18	//     whole-second time the terminal happens to print, and independently of
19	//     the timezone spelling of the instants;
20	//   - a baseline query obeys the same latest-record selection and online time
21	//     rule — the baseline only changes the quantity used by the missed-duty
22	//     alarm;
23	//   - a query time earlier than the greatest-seq record's collection time is
24	//     an error for both plain and baseline queries, even when a smaller-seq
25	//     record had already been collected by then, and no query or query failure
26	//     rewrites saved heartbeats.
27	
28	import (
29		"os"
30		"strings"
31		"testing"
32		"time"
33	)
34	
35	// mustParseRFC3339 parses a fixed test instant, failing the test rather than
36	// returning the zero time. Fractional seconds and explicit offsets are part of
37	// the input on purpose.
38	func mustParseRFC3339(t *testing.T, s string) time.Time {
39		t.Helper()
40		parsed, err := time.Parse(time.RFC3339, s)
41		if err != nil {
42			t.Fatalf("test setup: parse %q: %v", s, err)
43		}
44		return parsed
45	}
46	
47	// reconnectFixture is the disordered-history scenario: the greater-seq
48	// record was collected two minutes before the query (stale, offline), while
49	// the smaller-seq record was collected only ten seconds before the query
50	// (fresh). They also disagree on version, height and cumulative missed.
51	type reconnectFixture struct {
52		query     time.Time
53		bigSeq    Heartbeat // seq 10, collected 2 minutes ago
54		smallSeq  Heartbeat // seq 5, collected 10 seconds ago
55		latestAge time.Duration
56		freshAge  time.Duration
57	}
58	
59	func newReconnectFixture(t *testing.T) reconnectFixture {
60		t.Helper()
61		q := testBase
62		return reconnectFixture{
63			query:     q,
64			latestAge: 2 * time.Minute,
65			freshAge:  10 * time.Second,
66			bigSeq:    hb("recon", 10, q.Add(-2*time.Minute), "1.25.0", 1000, 5),
67			smallSeq:  hb("recon", 5, q.Add(-10*time.Second), "1.26.0", 900, 2),
68		}
69	}
70	
71	// assertHealthUsesBigSeq verifies a health result is derived entirely from the
72	// seq-10 record: offline because of its two-minute-old collection time, with
73	// its version, height and cumulative missed. A selector that instead picked
74	// the fresh seq-5 record (by receive order or newest collection time) would
75	// report online with version 1.26.0, height 900 and missed 2, and a selector
76	// that spliced fields would mismatch one of these.
77	func (f reconnectFixture) assertHealthUsesBigSeq(t *testing.T, r HealthResult) {
78		t.Helper()
79		if r.Seq != f.bigSeq.Seq {
80			t.Errorf("latest seq = %d, want %d (greatest seq, not freshest collection)", r.Seq, f.bigSeq.Seq)
81		}
82		if r.Status != "offline" {
83			t.Errorf("status = %q, want offline: the greatest-seq record is 2 minutes old; the fresh seq-%d record must not make the node online", r.Status, f.smallSeq.Seq)
84		}
85		if !r.CollectedAt.Equal(f.bigSeq.CollectedAt) {
86			t.Errorf("collected_at = %v, want %v (from seq %d, not the newer collection of seq %d)",
87				r.CollectedAt, f.bigSeq.CollectedAt, f.bigSeq.Seq, f.smallSeq.Seq)
88		}
89		if r.Version != f.bigSeq.Version {
90			t.Errorf("version = %q, want %q from seq %d; fields must not be spliced", r.Version, f.bigSeq.Version, f.bigSeq.Seq)
91		}
92		if r.Height != f.bigSeq.Height {
93			t.Errorf("height = %d, want %d from seq %d", r.Height, f.bigSeq.Height, f.bigSeq.Seq)
94		}
95		if r.Missed != f.bigSeq.Missed {
96			t.Errorf("cumulative missed = %d, want %d from seq %d", r.Missed, f.bigSeq.Missed, f.bigSeq.Seq)
97		}
98		joined := strings.Join(r.Findings, ";")
99		if !strings.Contains(joined, "offline") {
100			t.Errorf("findings %v must contain offline", r.Findings)
101		}
102		if !strings.Contains(joined, "version skew: 1.25.0 != 1.26.0") {
103			t.Errorf("findings %v must judge version skew from seq %d (1.25.0); the fresh seq-%d record's 1.26.0 must not mask it", r.Findings, f.bigSeq.Seq, f.smallSeq.Seq)
104		}
105	}
106	
107	// TestHealthLatestIsGreatestSeqRegardlessOfArrivalOrder saves the same two
108	// records in both possible arrival orders — stale big seq first (genuine
109	// backfill of the fresh small seq), and fresh small seq first (late arrival of
110	// the stale big seq) — and requires identical health results.
111	func TestHealthLatestIsGreatestSeqRegardlessOfArrivalOrder(t *testing.T) {
112		fx := newReconnectFixture(t)
113	
114		results := map[string]HealthResult{}
115		for _, order := range []struct {
116			name    string
117			submit1 func(*Store)
118			submit2 func(*Store)
119		}{
120			{
121				name: "stale big seq arrives first, fresh small seq backfilled later",
122				// seq 10 (collected 2m ago) is received 90s before the query; the
123				// smaller-seq record is not even submittable yet because its
124				// collection time is still in the future. It is backfilled at the
125				// query instant.
126				submit1: func(s *Store) { mustSubmit(t, s, fx.query.Add(-90*time.Second), fx.bigSeq) },
127				submit2: func(s *Store) { mustSubmit(t, s, fx.query, fx.smallSeq) },
128			},
129			{
130				name:    "fresh small seq arrives first, stale big seq delivered after",
131				submit1: func(s *Store) { mustSubmit(t, s, fx.query, fx.smallSeq) },
132				submit2: func(s *Store) { mustSubmit(t, s, fx.query, fx.bigSeq) },
133			},
134		} {
135			t.Run(order.name, func(t *testing.T) {
136				store, err := OpenStore(t.TempDir())
137				if err != nil {
138					t.Fatal(err)
139				}
140				order.submit1(store)
141				order.submit2(store)
142	
143				// Cumulative missed 5 (seq 10) strictly exceeds tolerance 4; the
144				// seq-5 record's count 2 would not. This makes the alarm another
145				// witness of which record drives the query.
146				r, err := store.Health("recon", fx.query, "1.26.0", 4)
147				if err != nil {
148					t.Fatal(err)
149				}
150				fx.assertHealthUsesBigSeq(t, r)
151				if !hasFinding(r.Findings, "missed duties above tolerance") {
152					t.Errorf("findings %v must alarm on cumulative missed=5 from seq %d", r.Findings, fx.bigSeq.Seq)
153				}
154				results[order.name] = r
155	
156				hist, err := store.History("recon")
157				if err != nil {
158					t.Fatal(err)
159				}
160				if len(hist) != 2 || hist[0].Seq != 5 || hist[1].Seq != 10 {
161					t.Fatalf("history must keep both gapped seqs ascending: %+v", hist)
162				}
163				if !hist[1].Equal(fx.bigSeq) || !hist[0].Equal(fx.smallSeq) {
164					t.Errorf("stored records altered: %+v / %+v", hist[0], hist[1])
165				}
166			})
167		}
168	
169		// Arrival order must leave no trace at all in the judgement.
170		a, b := results["stale big seq arrives first, fresh small seq backfilled later"],
171			results["fresh small seq arrives first, stale big seq delivered after"]
172		if a.Status != b.Status || a.Seq != b.Seq || a.Version != b.Version ||
173			a.Height != b.Height || a.Missed != b.Missed || !a.CollectedAt.Equal(b.CollectedAt) ||
174			strings.Join(a.Findings, "|") != strings.Join(b.Findings, "|") {
175			t.Errorf("health result depends on arrival order:\n%+v\nvs\n%+v", a, b)
176		}
177	}
178	
179	// TestHealthLateReplayOfSmallerSeqDoesNotRefreshLatest replays the smaller-seq
180	// record at a strictly later receive time, both as a first-time backfill and
181	// as a verbatim duplicate, and checks the latest telemetry's collection time
182	// and the offline judgement never move.
183	func TestHealthLateReplayOfSmallerSeqDoesNotRefreshLatest(t *testing.T) {
184		fx := newReconnectFixture(t)
185		store, err := OpenStore(t.TempDir())
186		if err != nil {
187			t.Fatal(err)
188		}
189	
190		// The stale big-seq record is the only telemetry known at the query time.
191		mustSubmit(t, store, fx.query.Add(-90*time.Second), fx.bigSeq)
192		before, err := store.Health("recon", fx.query, "1.26.0", 4)
193		if err != nil {
194			t.Fatal(err)
195		}
196		fx.assertHealthUsesBigSeq(t, before)
197	
198		// One minute later, the node re-connects and backfills the fresh small-seq
199		// record for the first time. Its receive time is later, but latest stays
200		// seq 10.
201		later := fx.query.Add(time.Minute)
202		newCount, dupCount, err := store.Submit([]Heartbeat{fx.smallSeq}, later)
203		if err != nil {
204			t.Fatalf("backfill of older seq must be accepted: %v", err)
205		}
206		if newCount != 1 || dupCount != 0 {
207			t.Errorf("first backfill: new=%d dup=%d, want 1/0", newCount, dupCount)
208		}
209		after, err := store.Health("recon", later, "1.26.0", 4)
210		if err != nil {
211			t.Fatal(err)
212		}
213		fx.assertHealthUsesBigSeq(t, after)
214		if !after.CollectedAt.Equal(before.CollectedAt) {
215			t.Errorf("backfill refreshed latest collection time: %v -> %v", before.CollectedAt, after.CollectedAt)
216		}
217	
218		// Re-submitting the very same record at yet another receive time is a
219		// duplicate and again changes nothing.
220		newCount, dupCount, err = store.Submit([]Heartbeat{fx.smallSeq}, later.Add(time.Minute))
221		if err != nil {
222			t.Fatalf("duplicate replay failed: %v", err)
223		}
224		if newCount != 0 || dupCount != 1 {
225			t.Errorf("duplicate replay: new=%d dup=%d, want 0/1", newCount, dupCount)
226		}
227		replayed, err := store.Health("recon", later.Add(time.Minute), "1.26.0", 4)
228		if err != nil {
229			t.Fatal(err)
230		}
231		fx.assertHealthUsesBigSeq(t, replayed)
232		if !replayed.CollectedAt.Equal(fx.bigSeq.CollectedAt) {
233			t.Errorf("duplicate replay moved collection time: %v", replayed.CollectedAt)
234		}
235	
236		hist, err := store.History("recon")
237		if err != nil {
238			t.Fatal(err)
239		}
240		if len(hist) != 2 {
241			t.Errorf("history len=%d, want 2 (duplicate not stored)", len(hist))
242		}
243	}
