245	// TestHealthOnlineBoundarySubSecondPrecision pins the exact 60-second edge
246	// using instants that carry sub-second fractions. Truncating collection or
247	// query time to whole seconds before comparing, or comparing the printed
248	// second numbers, would put the 60s+1ns case at exactly 60s and wrongly call
249	// it online.
250	func TestHealthOnlineBoundarySubSecondPrecision(t *testing.T) {
251		cases := []struct {
252			name      string
253			collected string
254			exact     string // age == 60s, still online
255			oneOver   string // age == 60s + 1 nanosecond, offline
256		}{
257			{
258				name:      "half-second fractions",
259				collected: "2026-10-01T12:00:00.5Z",
260				exact:     "2026-10-01T12:01:00.5Z",
261				oneOver:   "2026-10-01T12:01:00.500000001Z",
262			},
263			{
264				name:      "fraction rolls across the whole second",
265				collected: "2026-10-01T12:00:00.999999999Z",
266				exact:     "2026-10-01T12:01:00.999999999Z",
267				oneOver:   "2026-10-01T12:01:01Z",
268			},
269		}
270		for _, tc := range cases {
271			t.Run(tc.name, func(t *testing.T) {
272				store, err := OpenStore(t.TempDir())
273				if err != nil {
274					t.Fatal(err)
275				}
276				collected := mustParseRFC3339(t, tc.collected)
277				if _, _, err := store.Submit(
278					[]Heartbeat{hb("edge", 1, collected, "1.0", 1, 0)}, collected.Add(2*time.Minute)); err != nil {
279					t.Fatal(err)
280				}
281	
282				// Querying at the exact collection instant is allowed (age 0).
283				r, err := store.Health("edge", collected, "1.0", 0)
284				if err != nil {
285					t.Fatalf("query at collection instant must not error: %v", err)
286				}
287				if r.Status != "online" {
288					t.Errorf("age 0: status=%q, want online", r.Status)
289				}
290	
291				at := mustParseRFC3339(t, tc.exact)
292				if got := at.Sub(collected); got != 60*time.Second {
293					t.Fatalf("test setup: exact case age = %v, want 60s", got)
294				}
295				r, err = store.Health("edge", at, "1.0", 0)
296				if err != nil {
297					t.Fatalf("offline is a successful query, never an error: %v", err)
298				}
299				if r.Status != "online" {
300					t.Errorf("age exactly 60s: status=%q, want online", r.Status)
301				}
302	
303				over := mustParseRFC3339(t, tc.oneOver)
304				if got := over.Sub(collected); got != 60*time.Second+time.Nanosecond {
305					t.Fatalf("test setup: over case age = %v, want 60s+1ns", got)
306				}
307				r, err = store.Health("edge", over, "1.0", 0)
308				if err != nil {
309					t.Fatalf("offline query must succeed (exit-zero status): %v", err)
310				}
311				if r.Status != "offline" {
312					t.Errorf("age 60s+1ns: status=%q, want offline; whole-second truncation would misjudge this", r.Status)
313				}
314				if !hasFinding(r.Findings, "offline") {
315					t.Errorf("findings %v must contain the offline notice", r.Findings)
316				}
317			})
318		}
319	}
320	
321	// TestHealthOnlineBoundaryTimezoneInvariant states the same boundary pair in
322	// different timezone spellings and requires the same status and the preserved
323	// sub-second instant. Online/offline compares instants, not local wall-clock
324	// text.
325	func TestHealthOnlineBoundaryTimezoneInvariant(t *testing.T) {
326		store, err := OpenStore(t.TempDir())
327		if err != nil {
328			t.Fatal(err)
329		}
330		collectedZ := mustParseRFC3339(t, "2026-10-01T12:00:00.5Z")
331		if _, _, err := store.Submit(
332			[]Heartbeat{hb("tz", 1, collectedZ, "1.0", 1, 0)},
333			mustParseRFC3339(t, "2026-10-01T12:02:00Z")); err != nil {
334			t.Fatal(err)
335		}
336	
337		// The same instant written with +08:00 is the same heartbeat: duplicate,
338		// not a second record.
339		sameInstantOffset := hb("tz", 1, mustParseRFC3339(t, "2026-10-01T20:00:00.5+08:00"), "1.0", 1, 0)
340		newCount, dupCount, err := store.Submit([]Heartbeat{sameInstantOffset},
341			mustParseRFC3339(t, "2026-10-01T20:02:00+08:00"))
342		if err != nil {
343			t.Fatal(err)
344		}
345		if newCount != 0 || dupCount != 1 {
346			t.Errorf("same instant in another timezone: new=%d dup=%d, want 0/1", newCount, dupCount)
347		}
348	
349		// Exactly 60s and 60s+1ns, each expressed in two different zones.
350		onlineZ := mustParseRFC3339(t, "2026-10-01T12:01:00.5Z")
351		onlineOffset := mustParseRFC3339(t, "2026-10-01T20:01:00.5+08:00")
352		if !onlineZ.Equal(onlineOffset) {
353			t.Fatal("test setup: online instants differ")
354		}
355		offlineZ := mustParseRFC3339(t, "2026-10-01T12:01:00.500000001Z")
356		offlineMinus := mustParseRFC3339(t, "2026-10-01T08:01:00.500000001-04:00")
357		if !offlineZ.Equal(offlineMinus) {
358			t.Fatal("test setup: offline instants differ")
359		}
360	
361		for _, q := range []time.Time{onlineZ, onlineOffset} {
362			r, err := store.Health("tz", q, "1.0", 0)
363			if err != nil {
364				t.Fatal(err)
365			}
366			if r.Status != "online" {
367				t.Errorf("query %s: status=%q, want online at exactly 60s", q.Format(time.RFC3339Nano), r.Status)
368			}
369			if r.CollectedAt.Nanosecond() != 500_000_000 || !r.CollectedAt.Equal(collectedZ) {
370				t.Errorf("fractional precision lost: collected=%v (nanos=%d), want %v",
371					r.CollectedAt.Format(time.RFC3339Nano), r.CollectedAt.Nanosecond(), collectedZ.Format(time.RFC3339Nano))
372			}
373		}
374		for _, q := range []time.Time{offlineZ, offlineMinus} {
375			r, err := store.Health("tz", q, "1.0", 0)
376			if err != nil {
377				t.Fatal(err)
378			}
379			if r.Status != "offline" {
380				t.Errorf("query %s: status=%q, want offline at 60s+1ns regardless of zone", q.Format(time.RFC3339Nano), r.Status)
381			}
382			if r.CollectedAt.Nanosecond() != 500_000_000 {
383				t.Errorf("fractional precision lost in offline result: nanos=%d", r.CollectedAt.Nanosecond())
384			}
385		}
386	
387		// The fraction survives persistence across a reopen.
388		reopened, err := OpenStore(store.Dir())
389		if err != nil {
390			t.Fatal(err)
391		}
392		hist, err := reopened.History("tz")
393		if err != nil {
394			t.Fatal(err)
395		}
396		if len(hist) != 1 || !hist[0].CollectedAt.Equal(collectedZ) || hist[0].CollectedAt.Nanosecond() != 500_000_000 {
397			t.Errorf("fractional collection time not preserved in stored history: %+v", hist)
398		}
399	}
400	
401	// TestHealthSinceBaselineFollowsSameLatestAndOnlineRules checks that a
402	// missed-since baseline changes only the missed-duty alarm quantity: the
403	// latest record is still the greatest seq, status is still set by its
404	// collection time, version skew is still judged from it, and the first-line
405	// missed is still its cumulative count.
406	func TestHealthSinceBaselineFollowsSameLatestAndOnlineRules(t *testing.T) {
407		fx := newReconnectFixture(t)
408		store, err := OpenStore(t.TempDir())
409		if err != nil {
410			t.Fatal(err)
411		}
412		mustSubmit(t, store, fx.query.Add(-90*time.Second), fx.bigSeq)
413		mustSubmit(t, store, fx.query, fx.smallSeq)
414	
415		// Baseline is the fresh seq-5 record. Its version happens to match the
416		// expected version and its missed count 2 would look healthy — neither may
417		// influence the result: new missed duties are 5-2=3, but status is offline
418		// and the skew comes from the stale seq-10 record.
419		r, err := store.HealthSince("recon", fx.query, "1.26.0", 2, fx.smallSeq.Seq)
420		if err != nil {
421			t.Fatal(err)
422		}
423		if r.Status != "offline" {
424			t.Errorf("baseline must not determine online status: got %q, want offline", r.Status)
425		}
426		if r.Seq != fx.bigSeq.Seq || !r.CollectedAt.Equal(fx.bigSeq.CollectedAt) {
427			t.Errorf("latest must stay seq %d, got seq %d at %v", fx.bigSeq.Seq, r.Seq, r.CollectedAt)
428		}
429		if r.Version != fx.bigSeq.Version || r.Height != fx.bigSeq.Height {
430			t.Errorf("displayed fields must come from seq %d: version=%q height=%d", fx.bigSeq.Seq, r.Version, r.Height)
431		}
432		if r.Missed != fx.bigSeq.Missed {
433			t.Errorf("first-line cumulative missed = %d, want %d from the latest record", r.Missed, fx.bigSeq.Missed)
434		}
435		if r.BaselineSeq != fx.smallSeq.Seq || r.BaselineMissed != fx.smallSeq.Missed {
436			t.Errorf("baseline = seq %d/missed %d, want %d/%d", r.BaselineSeq, r.BaselineMissed, fx.smallSeq.Seq, fx.smallSeq.Missed)
437		}
438		if !r.NewMissedKnown || r.NewMissed != 3 {
439			t.Errorf("new missed = known:%v %d, want true/3 (5-2)", r.NewMissedKnown, r.NewMissed)
440		}
441		joined := strings.Join(r.Findings, ";")
442		if !strings.Contains(joined, "offline") || !strings.Contains(joined, "version skew: 1.25.0 != 1.26.0") {
443			t.Errorf("baseline must not suppress offline/version-skew findings: %v", r.Findings)
444		}
445		if !strings.Contains(joined, "above tolerance") {
446			t.Errorf("new=3 strictly over tolerance 2 must alarm: %v", r.Findings)
447		}
448	
449		// Equality with the tolerance must not alarm, while status stays offline.
450		r, err = store.HealthSince("recon", fx.query, "1.26.0", 3, fx.smallSeq.Seq)
451		if err != nil {
452			t.Fatal(err)
453		}
454		if r.Status != "offline" {
455			t.Errorf("status=%q, want offline even when the miss alarm is silent", r.Status)
456		}
457		if hasFinding(r.Findings, "missed duties above tolerance") {
458			t.Errorf("new=3 with tolerance 3 must not alarm: %v", r.Findings)
459		}
460	
461		// Baseline equal to the latest record: new missed is 0, latest rules unchanged.
462		r, err = store.HealthSince("recon", fx.query, "1.26.0", 0, fx.bigSeq.Seq)
463		if err != nil {
464			t.Fatal(err)
465		}
466		if r.Status != "offline" || r.Seq != fx.bigSeq.Seq || r.Missed != fx.bigSeq.Missed {
467			t.Errorf("baseline==latest: %+v, want offline seq %d missed %d", r, fx.bigSeq.Seq, fx.bigSeq.Missed)
468		}
469		if !r.NewMissedKnown || r.NewMissed != 0 || r.BaselineMissed != fx.bigSeq.Missed {
470			t.Errorf("baseline==latest new missed = known:%v %d baseline=%d, want true/0/%d",
471				r.NewMissedKnown, r.NewMissed, r.BaselineMissed, fx.bigSeq.Missed)
472		}
473	}
474	
475	// TestHealthQueryEarlierThanLatestCollectionErrorsWithoutFallback builds a
476	// history where a smaller-seq record genuinely exists before the requested
477	// query instant while the greatest-seq record does not yet exist at that
478	// instant. Both plain and baseline queries must error instead of rewinding to
479	// the older record and reporting it healthy.
480	func TestHealthQueryEarlierThanLatestCollectionErrorsWithoutFallback(t *testing.T) {
481		store, err := OpenStore(t.TempDir())
482		if err != nil {
483			t.Fatal(err)
484		}
485		q := testBase
486		old := hb("clock", 4, q.Add(-3*time.Minute), "1.0", 100, 0)
487		latest := hb("clock", 8, q.Add(-2*time.Minute), "1.0", 104, 0)
488		mustSubmit(t, store, q, old, latest)
489	
490		// q-150s: seq 4 (q-180s) has already been collected, but the query is 30s
491		// before the greatest-seq record's collection time (q-120s).
492		at := q.Add(-150 * time.Second)
493		if !latest.CollectedAt.After(at) || at.Before(old.CollectedAt) {
494			t.Fatal("test setup: query must sit between the two collection times")
495		}
496	
497		_, err = store.Health("clock", at, "1.0", 0)
498		if err == nil {
499			t.Fatal("plain query earlier than the latest record's collection time must error instead of falling back to seq 4")
500		}
501		if !strings.Contains(err.Error(), "earlier than collection") {
502			t.Errorf("error should explain the query is earlier than collection: %v", err)
503		}
504	
505		// A valid baseline (seq 4 exists) changes nothing: the latest-record time
506		// rule is enforced before any result is returned, and the baseline record
507		// must not be promoted to the answer.
508		_, err = store.HealthSince("clock", at, "1.0", 0, old.Seq)
509		if err == nil {
510			t.Fatal("baseline query earlier than the latest record's collection time must error")
511		}
512		if !strings.Contains(err.Error(), "earlier than collection") {
513			t.Errorf("baseline error should explain the time ordering: %v", err)
514		}
515	
516		// The same instants queried at/after the latest collection succeed, still
517		// anchored to the greatest seq — proving the rejection is about time, not
518		// the data.
519		r, err := store.Health("clock", q, "1.0", 0)
520		if err != nil {
521			t.Fatal(err)
522		}
523		if r.Seq != latest.Seq || r.Status != "offline" {
524			t.Errorf("later query: %+v, want seq %d offline", r, latest.Seq)
525		}
526		r, err = store.HealthSince("clock", q, "1.0", 0, old.Seq)
527		if err != nil {
528			t.Fatal(err)
529		}
530		if r.Seq != latest.Seq || r.Status != "offline" || !r.NewMissedKnown {
531			t.Errorf("later baseline query: %+v, want seq %d offline with a known new-miss count", r, latest.Seq)
532		}
533	
534		// Querying the exact greatest-seq collection instant is allowed (the
535		// boundary is strict "before"), including with a fraction.
536		fractionalLatest := hb("clock-frac", 8,
537			mustParseRFC3339(t, "2026-10-01T12:00:00.25Z"), "1.0", 104, 0)
538		mustSubmit(t, store, mustParseRFC3339(t, "2026-10-01T12:02:00Z"), fractionalLatest)
539		exact := mustParseRFC3339(t, "2026-10-01T12:00:00.25Z")
540		r, err = store.Health("clock-frac", exact, "1.0", 0)
541		if err != nil {
542			t.Fatalf("query at the exact (fractional) collection instant must be allowed: %v", err)
543		}
544		if r.Status != "online" {
545			t.Errorf("at exact collection instant status=%q, want online", r.Status)
546		}
547	}
548	
549	// TestHealthQueriesNeverMutateStoredHeartbeats snapshots the saved files and
550	// runs every kind of read — successful online/offline/notelemetry, baseline
551	// known and rollback-unknown, and the failing early-query and bad-baseline
552	// paths — then requires the stored heartbeats to be byte-for-byte unchanged,
553	// including fractional collection instants. A failed query must not create a
554	// node file either.
555	func TestHealthQueriesNeverMutateStoredHeartbeats(t *testing.T) {
556		dir := t.TempDir()
557		store, err := OpenStore(dir)
558		if err != nil {
559			t.Fatal(err)
560		}
561		q := testBase
562	
563		// Disordered offline node, a fresh online node, and a counter-reset node
564		// for the rollback baseline path.
565		mustSubmit(t, store, q.Add(-90*time.Second),
566			hb("recon", 10, q.Add(-2*time.Minute), "1.25.0", 1000, 5))
567		mustSubmit(t, store, q,
568			hb("recon", 5, q.Add(-10*time.Second), "1.26.0", 900, 2),
569			hb("fresh", 1, mustParseRFC3339(t, "2026-10-01T11:59:59.5Z"), "1.0", 7, 0),
570			hb("reset", 1, q.Add(-3*time.Second), "1.0", 1, 12),
571			hb("reset", 2, q.Add(-2*time.Second), "1.0", 2, 5),
572			hb("reset", 3, q.Add(-time.Second), "1.0", 3, 14),
573		)
574	
575		snapshot := map[string]string{}
576		for _, node := range []string{"recon", "fresh", "reset"} {
577			b, err := os.ReadFile(store.nodePath(node))
578			if err != nil {
579				t.Fatal(err)
580			}
581			snapshot[node] = string(b)
582		}
583	
584		if _, err := store.Health("recon", q, "1.26.0", 4); err != nil {
585			t.Fatal(err)
586		}
587		if _, err := store.Health("fresh", q, "1.0", 0); err != nil {
588			t.Fatal(err)
589		}
590		if r, err := store.Health("ghost", q, "1.0", 0); err != nil || r.Status != "notelemetry" {
591			t.Fatalf("unknown node: r=%+v err=%v, want notelemetry/nil", r, err)
592		}
593		if _, err := store.HealthSince("recon", q, "1.26.0", 2, 5); err != nil {
594			t.Fatal(err)
595		}
596		if r, err := store.HealthSince("reset", q, "1.0", 2, 1); err != nil {
597			t.Fatal(err)
598		} else if r.NewMissedKnown || !hasFinding(r.Findings, "累计漏签数回退") {
599			t.Fatalf("rollback query: %+v, want unknown new missed with rollback finding", r)
600		}
601		if _, err := store.Health("recon", q.Add(-3*time.Minute), "1.26.0", 4); err == nil {
602			t.Error("early plain query should fail")
603		}
604		if _, err := store.HealthSince("recon", q.Add(-3*time.Minute), "1.26.0", 2, 5); err == nil {
605			t.Error("early baseline query should fail")
606		}
607		if _, err := store.HealthSince("recon", q, "1.26.0", 2, 99); err == nil {
608			t.Error("baseline above latest should fail")
609		}
610	
611		// Querying an unknown node must not have created its file.
612		if _, err := os.Stat(store.nodePath("ghost")); !os.IsNotExist(err) {
613			t.Errorf("querying an unknown node created a file: stat err=%v", err)
614		}
615	
616		for node, before := range snapshot {
617			after, err := os.ReadFile(store.nodePath(node))
618			if err != nil {
619				t.Fatal(err)
620			}
621			if string(after) != before {
622				t.Errorf("saved heartbeats for %q changed during queries/failures", node)
623			}
624		}
625	
626		// Reopen and confirm content semantics, especially the fractional time.
627		reopened, err := OpenStore(dir)
628		if err != nil {
629			t.Fatal(err)
630		}
631		hist, err := reopened.History("recon")
632		if err != nil || len(hist) != 2 || hist[1].Seq != 10 {
633			t.Fatalf("recon history after queries: %+v err=%v", hist, err)
634		}
635		freshHist, err := reopened.History("fresh")
636		if err != nil || len(freshHist) != 1 || freshHist[0].CollectedAt.Nanosecond() != 500_000_000 {
637			t.Fatalf("fresh history fraction lost: %+v err=%v", freshHist, err)
638		}
639	}
